<?php define('TT_BROWSE_TYPE','group');define('TT_BROWSE_TITLE','Groups');define('TT_NAV_ACTIVE','group.php');
require_once __DIR__.'/core.php';require_once __DIR__.'/collection_lib.php';tt_require_login();
$db=tt_db_open(true);[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`name`,p.`scope`,p.`type`,p.`comments`,p.`recipients`,a.`filename` attachment_filename,a.`mime_type` attachment_mime FROM `posts` p LEFT JOIN `post_attachments` a ON a.`post_id`=p.`id` WHERE '.$vis.' AND p.`type`=\'group\' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 150';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();$media=array_values(array_filter($rows,fn($r)=>trim((string)$r['attachment_filename'])!==''));
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Groups</title></head><body><?php tt_nav(TT_NAV_ACTIVE);?><main class="content"><div class="actions"><a href="create.php?mode=group">Create</a><a href="calls.php?scope=group">Group call</a><a href="post.php?type=group">Search groups</a></div><h2>Groups · gallery</h2><p class="meta">Groups are gallery-first: attached images, audio, video and files are surfaced before the discussion stream.</p><section class="collection-gallery"><?php foreach($media as $r):?><?=tt_collection_attachment_html($r)?><?php endforeach;?><?php if(!$media):?><article class="card">No group attachments yet.</article><?php endif;?></section><h2>Group posts</h2><section class="grid"><?php foreach($rows as $r):$targetUser=tt_reply_target_user((string)$r['name'],(string)$r['recipients'],(string)($_SESSION['name']??''));?><article class="card post-card" id="post-<?=(int)$r['id']?>" data-post-expandable="1" aria-expanded="false"><h3><?=tt_h($r['title'])?></h3><p class="meta">#<?=(int)$r['id']?> · <?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?> · <?=tt_h(trim($r['scope']))?></p><p><?=nl2br(tt_h($r['content']))?></p><?php if($r['tags']!==''):?><p class="meta">Tags: <?=tt_h($r['tags'])?></p><?php endif;?><div class="actions"><a href="<?=tt_h(tt_compose_url('comment',(int)$r['id'],(string)$r['name'],'group',(string)$r['title'],trim((string)$r['scope']),$targetUser))?>">Comment</a></div></article><?php endforeach;?><?php if(!$rows):?><article class="card">No groups yet.</article><?php endif;?></section></main><script src="nsfw-blur.js?v=20260915c" defer></script></body></html>
